</section><script>const productSelect=document.getElementById('product_id');const quantityInput=document.getElementById('quantity');const totalLabel=document.getElementById('estimated-total');function estimate(){const price=Number(productSelect.selectedOptions[0]?.dataset.price||0);const quantity=Number(quantityInput.value||0);totalLabel.textContent=new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(price*Math.max(0,quantity));}productSelect.addEventListener('change',estimate);quantityInput.addEventListener('input',estimate);estimate();</script>
